{
  "summary": "Added an enum quality 'location' tracking whether the crew is on the street, in the lobby, or in the vault. It is extractor-sourced with a visible-choice read so a judge can read it each turn.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "location",
        "type": "enum",
        "source": "extractor",
        "rubric": "Where is the crew right now: street, lobby, or vault?",
        "values": ["street", "lobby", "vault"],
        "read_as": "choice"
      }
    }
  ]
}

{
  "summary": "Proposing the core quality set for the story. Since the premise is still untitled and open, I'm choosing a compact, broadly reusable dramatic-state model: tension, trust, resolve, and a couple of scene-readable flags. These give the extractor enough to judge each beat without overfitting to a genre we haven't locked yet.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "tension",
        "type": "int",
        "source": "extractor",
        "rubric": "On a scale of 0-10, how much unresolved dramatic pressure is present in this beat? 0 is calm and safe, 10 is imminent crisis.",
        "read_as": "rating"
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "trust",
        "type": "int",
        "source": "extractor",
        "rubric": "On a scale of 0-10, how much does the protagonist trust the people around them right now? 0 is total suspicion, 10 is complete faith.",
        "read_as": "rating"
      }
    },
    {
      "kind": "addQuality",
      "type": "int",
      "source": "extractor",
      "rubric": "On a scale of 0-10, how determined is the protagonist to push forward despite obstacles in this beat? 0 is giving up, 10 is unstoppable.",
      "key": "resolve",
      "read_as": "rating"
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "protagonist_alone",
        "type": "bool",
        "source": "extractor",
        "rubric": "Is the protagonist physically alone in this beat, with no other character present?",
        "read_as": "choice"
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "location",
        "type": "string",
        "source": "extractor",
        "rubric": "What is the name of the place where this beat takes place? Answer with a short noun phrase.",
        "read_as": "stated"
      }
    }
  ]
}

{
  "summary": "Declared the core dramatic-state qualities for the story: tension (scene pressure), trust (how much the protagonist is trusted by others), and a boolean flag for whether the protagonist's secret has been exposed. All are extractor-sourced so the judge can read them from prose each turn.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "tension",
        "type": "int",
        "source": "extractor",
        "read_as": "rating",
        "rubric": "from 1 (calm, low stakes) to 5 (critical, explosive pressure)",
        "monotonic": false
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "trust",
        "type": "int",
        "source": "extractor",
        "read_as": "rating",
        "rubric": "from 1 (openly distrusted or suspected) to 5 (fully trusted and relied upon)",
        "monotonic": false
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "secret_exposed",
        "type": "bool",
        "source": "extractor",
        "read_as": "choice",
        "rubric": "Has the protagonist's secret been revealed to someone who did not already know it?",
        "latching": true
      }
    }
  ]
}

{
