      "kind": "addCheckpoint",
      "checkpoint": {
        "id": "lobby",
        "name": "The Lobby Door",
        "objective": "Crack the lobby door and get the crew inside the bank.",
        "type": "intermediate",
        "tension_target": "tense"
      }
    },
    {
      "kind": "removeTransition",
      "ref": { "from": "start", "to": "vault" }
    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "start",
        "to": "lobby",
        "priority": 1,
        "gate": { "q": "has_key", "op": "==", "v": true }
      }
    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "lobby",
        "to": "vault",
        "priority": 1,
        "gate": { "q": "lobby_open", "op": "==", "v": true }
      }
    }
  ]
}

{
