    {
      "kind": "addTransition",
      "transition": {
        "from": "camp",
        "to": "ruins",
        "gate": { "q": "agreed_to_go", "op": "==", "v": true },
        "priority": 1,
        "effects": { "progress": { "anchor": "ruins", "amount": 1 } }
