    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "ruins",
        "to": "chamber",
        "gate": { "q": "torch_lit", "op": "==", "v": true },
        "priority": 1,
        "effects": { "progress": { "anchor": "chamber", "amount": 1 } }
