{
  "summary": "The story's roster names Vex (the crew's lockpick), who does not exist on this install, and the story leans on its own lorebook 'Vault Job Lore' (already present, so entries may be written into it). I'll create a character card for Vex with a one-line role, add lorebook entries for the bank, the vault, and the key the crew needs, and form a group that plays the job. No ops for existing assets (Assistant, Arin, Ponticius, Adolion, Sun Ruins Party).",
  "ops": [
    {
      "kind": "createCharacterCard",
      "name": "Vex",
      "description": "A wiry, sharp-eyed thief in worn leathers, Vex is the crew's lockpick — patient with tumblers, impatient with everything else. She talks in clipped, practical sentences and keeps a set of picks wrapped in oilcloth.",
      "role": "The crew's lockpick",
      "personality": "Cynical, precise, dry-humored, loyal to the job rather than the people on it.",
      "scenario": "Vex has been hired for a vault job against the city bank and is casing the building alongside the rest of the crew.",
      "first_mes": "Vex crouches by the bank's service door, picks already out. \"Two tumblers, maybe three. Give me a minute and don't breathe so loud.\"",
      "mes_example": "<START>\n{{user}}: Can you get us in?\nVex: \"Through this door? Yes. Through the vault? That's a different conversation, and it starts with the key.\"",
      "tags": ["thief", "rogue", "heist", "lockpick"]
    },
    {
      "kind": "upsertLorebookEntry",
      "lorebook": "Vault Job Lore",
      "comment": "The City Bank",
      "keys": ["bank", "city bank", "the bank"],
      "content": "The City Bank is a stone-faced building on the main square, staffed by day and guarded by night. Its service door is the crew's way in; the vault lies below the main floor behind a reinforced steel door."
    },
    {
      "kind": "upsertLorebookEntry",
      "lorebook": "Vault Job Lore",
      "comment": "The Vault",
      "keys": ["vault", "the vault", "steel door"],
      "content": "The bank's vault is a reinforced steel chamber below the main floor. It cannot be picked open — it requires the vault key, held by the bank manager, to release the locking bars."
    },
    {
      "kind": "upsertLorebookEntry",
      "lorebook": "Vault Job Lore",
      "comment": "The Vault Key",
      "keys": ["vault key", "the key", "key"],
      "content": "The vault key is a heavy brass key carried by the bank manager. Without it the vault cannot be opened; obtaining it is the crew's first objective."
    },
    {
      "kind": "createGroup",
      "name": "The Vault Job Crew",
      "members": ["Vex"]
    }
  ]
}

{
  "summary": "Provisioning for The Vault Job: create the crew's lockpick Vex as a character card, create the story's own lorebook 'Vault Job Lore', write the entries the heist leans on (the bank, the vault, the key), and form the crew group that plays the story. No existing assets are touched.",
  "ops": [
    {
      "kind": "createCharacterCard",
      "name": "Vex",
      "description": "Vex is the crew's lockpick: a wiry, patient safecracker who talks to tumblers like they're old friends. She carries a roll of picks, a stethoscope, and a grudge against every lock that's ever beaten her. In the field she's calm and precise; off the clock she's restless, superstitious, and allergic to plans that don't have a second exit.",
      "role": "The crew's lockpick — she gets the vault key and cracks the vault itself.",
      "personality": "Patient, precise, dryly funny, superstitious, quietly proud of her craft.",
      "scenario": "Vex has been hired for a job on the city bank's vault. She needs the key first, then the door.",
      "first_mes": "Vex rolls a pick between her fingers and looks up at the bank's marble face. \"Key first,\" she says. \"Then I'll introduce myself to the lock.\"",
      "mes_example": "<START>\n{{user}}: Can you open it?\n{{user}}: Vex\nVex: \"Give me a minute and a reason.\" She kneels, ear to the door, and goes very still.",
      "tags": ["thief", "lockpick", "heist", "crew"]
    },
    {
      "kind": "createStoryLorebook",
      "name": "Vault Job Lore"
    },
    {
      "kind": "upsertLorebookEntry",
      "lorebook": "Vault Job Lore",
      "comment": "The City Bank",
      "keys": ["bank", "city bank", "the bank"],
      "content": "The city bank is a marble-faced institution in the old quarter, open six days a week and guarded by two night watchmen and a bell that rings on the hour. Its public floor is ordinary; its lower level is not. The crew has been casing it for a week.",
      "constant": true
    },
    {
      "kind": "upsertLorebookEntry",
      "lorebook": "Vault Job Lore",
      "comment": "The Vault",
      "keys": ["vault", "the vault", "vault door"],
      "content": "The vault sits below the bank's public floor behind a steel door with a three-tumbler lock and a time-delay bolt. It cannot be opened without the vault key and a steady hand. Vex is the only one in the crew who can work the tumblers.",
      "constant": true
    },
    {
      "kind": "upsertLorebookEntry",
      "lorebook": "Vault Job Lore",
      "comment": "The Vault Key",
      "keys": ["key", "vault key", "the key"],
      "content": "The vault key is a brass key on a short chain, kept by the bank's head clerk and worn around his neck during the day. Without it the vault stays shut. Getting the key is the crew's first objective.",
      "constant": true
    },
    {
      "kind": "createGroup",
      "name": "Vault Job Crew",
      "members": ["Vex"]
    }
  ]
}

{
  "summary": "Added an intermediate checkpoint, The Ossuary, between the Entrance and the Crypt. The party discovers the relic is a fake there, so I introduced a latching boolean quality `relic_is_fake` to capture that reveal, plus a `relic_recovered` quality to track whether they actually take the relic. The Ossuary sits at a tense tension target, and I wired transitions so the party passes through it on the way to the Crypt.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "relic_is_fake",
        "type": "bool",
        "source": "extractor",
        "rubric": "Has the party discovered that the relic is a fake?",
        "latching": true
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "relic_recovered",
        "type": "bool",
        "source": "extractor",
        "rubric": "Has the party taken the relic into their possession?"
      }
    },
    {
      "kind": "addCheckpoint",
      "checkpoint": {
        "id": "ossuary",
        "name": "The Ossuary",
        "objective": "Discover that the relic is a fake.",
        "type": "intermediate",
        "tension_target": "tense",
        "guidance": "The party reaches a bone-lined chamber where the relic is displayed. On close inspection, the relic proves to be a forgery — a gilded copy planted to mislead seekers. Let the reveal land before they push on toward the Crypt."
      }
    },
    {
      "kind": "setCheckpointSnapshot",
      "id": "ossuary",
      "snapshot": {
        "relic_is_fake": true
      }
    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "entrance",
        "to": "ossuary",
        "priority": 1,
        "gate": {
          "q": "door_open",
          "op": "==",
          "v": true
        }
      }
    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "ossuary",
        "to": "crypt",
        "priority": 1,
        "gate": {
          "q": "relic_is_fake",
          "op": "==",
          "v": true
        }
      }
    }
  ]
}

